@using sv_6496b81a2b51455bb874618baf7e58c7.Services

<div class="change-password-panel">
    <div class="panel-header" @onclick="ToggleExpanded">
        <h3>Change Password</h3>
        <span class="expand-icon">@(isExpanded ? "▼" : "▶")</span>
    </div>

    @if (isExpanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label>Current Password</label>
                <input type="password" @bind="currentPassword" />
            </div>

            <div class="form-group">
                <label>New Password</label>
                <input type="password" @bind="newPassword" />
            </div>

            <div class="form-group">
                <label>Confirm New Password</label>
                <input type="password" @bind="confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="toast-message toast-error">@errorMessage</div>
            }
            @if (!string.IsNullOrEmpty(successMessage))
            {
                <div class="toast-message toast-success">@successMessage</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@isUpdating">
                @(isUpdating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isExpanded;
    private string currentPassword = string.Empty;
    private string newPassword = string.Empty;
    private string confirmPassword = string.Empty;
    private string errorMessage = string.Empty;
    private string successMessage = string.Empty;
    private bool isUpdating;

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePassword()
    {
        errorMessage = string.Empty;
        successMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            errorMessage = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        isUpdating = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            successMessage = "Password updated successfully!";
            currentPassword = string.Empty;
            newPassword = string.Empty;
            confirmPassword = string.Empty;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to update password: {ex.Message}";
        }
        finally
        {
            isUpdating = false;
        }
    }
}

@using sv_6496b81a2b51455bb874618baf7e58c7.Services

<div class="active-sessions">
    <h3>Active Sessions</h3>
    <table class="sessions-table">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th>Action</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session)">
                                Revoke
                            </button>
                        }
                        else
                        {
                            <span class="current-session-badge">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

<ConfirmationDialog
    IsVisible="@showConfirmDialog"
    Title="Revoke Session"
    Message="@($"Are you sure you want to revoke the session on {sessionToRevoke?.Device} ({sessionToRevoke?.Location})?")"
    ConfirmText="Revoke"
    OnConfirm="ConfirmRevoke"
    OnCancel="CancelRevoke" />

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private bool showConfirmDialog;
    private ActiveSession? sessionToRevoke;

    private void RequestRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showConfirmDialog = true;
    }

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(sessionToRevoke.Id);
        }
        showConfirmDialog = false;
        sessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        showConfirmDialog = false;
        sessionToRevoke = null;
    }
}

@using sv_6496b81a2b51455bb874618baf7e58c7.Services

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (settings is not null)
