@using sv_6496b81a2b51455bb874618baf7e58c7.Services

<div class="appearance-preview" style="@PreviewStyle">
    <div class="preview-header">Preview</div>
    <div class="preview-content">
        <h4>Sample Heading</h4>
        <p>This is how your content will look with the selected settings.</p>
        <button class="btn btn-primary">Sample Button</button>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public bool CompactMode { get; set; }

    private string PreviewStyle
    {
        get
        {
            var bg = Theme switch
            {
                "Dark" => "background-color: #1e1e1e; color: #e0e0e0;",
                "System" => "background-color: #2d2d2d; color: #d4d4d4;",
                _ => "background-color: #ffffff; color: #333333;"
            };
            var font = FontSize switch
            {
                "Small" => "font-size: 12px;",
                "Large" => "font-size: 18px;",
                _ => "font-size: 14px;"
            };
            var padding = CompactMode ? "padding: 8px;" : "padding: 16px;";
            return $"{bg} {font} {padding}";
        }
    }
}

@using sv_6496b81a2b51455bb874618baf7e58c7.Services

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (loaded)
    {
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in themes)
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(selectedTheme == theme)"
                               @onchange="() => selectedTheme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in fontSizes)
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(selectedFontSize == size)"
                               @onchange="() => selectedFontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label>Language</label>
            <select @bind="selectedLanguage">
                @foreach (var lang in languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="toggle-group">
            <label class="toggle-item">
                <span>Compact Mode</span>
                <input type="checkbox" @bind="compactMode" class="toggle-switch" />
            </label>
        </div>

        <AppearancePreview Theme="@selectedTheme" FontSize="@selectedFontSize" CompactMode="@compactMode" />

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="toast-message toast-success">@statusMessage</div>
        }
    }
    else
    {
        <p>Loading appearance settings...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool loaded;
    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private string statusMessage = string.Empty;

    private static readonly string[] themes = { "Light", "Dark", "System" };
    private static readonly string[] fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        if (settings is not null)
        {
            selectedTheme = settings.Theme;
            selectedFontSize = settings.FontSize;
            selectedLanguage = settings.Language;
            compactMode = settings.CompactMode;
        }
        loaded = true;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        statusMessage = "Appearance saved!";
        StateHasChanged();
        _ = ClearMessage();
    }

    private async Task ClearMessage()
    {
        await Task.Delay(3000);
        statusMessage = string.Empty;
        await InvokeAsync(StateHasChanged);
    }
}

